// Each entry is pushed into its global list and gets an explicit trades.set with the list's multiplier.
// The guard checks global.trades, so an id already priced by globalRegistry.js is left alone.
// NOTE: do NOT check Item.exists() here. Startup scripts load in KubeJSForge's constructor
// (mod construction), before the item registry is populated, so Item.exists() returns false
// for every modded item and the whole list gets silently dropped. Every id below was checked
// against the mod jars (models/blockstates/textures) instead.

const applyExtraPrices = (entries, list, multiplier, valueType) => {
  entries.forEach((entry) => {
    const item = entry.item;
    const value = entry.value;
    if (global.trades.has(item)) return;
    list.push({ item: item, value: value });
    global.trades.set(item, {
      value: global.getConfiguredValue(value, valueType),
      multiplier: multiplier,
    });
  });
};
applyExtraPrices(extraCooking, global.cooking, "shippingbin:crop_sell_multiplier", "crop");
applyExtraPrices(extraAnimalProducts, global.animalProducts, "shippingbin:crop_sell_multiplier", "crop");
applyExtraPrices(extraMiscAdventurer, global.miscAdventurer, "shippingbin:meat_sell_multiplier", "meat");
